class Solution {
public:
    int maximumsSplicedArray(std::vector<int>& nums1, std::vector<int>& nums2) {
        auto kadane = [](const std::vector<int>& a, const std::vector<int>& b) {
            int max_gain = 0, cur = 0, total = 0;
            for (size_t i = 0; i < a.size(); ++i) {
                total += a[i];
                cur = std::max(0, cur + b[i] - a[i]);
                max_gain = std::max(max_gain, cur);
            }
            return total + max_gain;
        };
        return std::max(kadane(nums1, nums2), kadane(nums2, nums1));
    }
};

class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        return Math.max(kadane(nums1, nums2), kadane(nums2, nums1));
    }
    private int kadane(int[] a, int[] b) {
        int maxGain = 0, cur = 0, total = 0;
        for (int i = 0; i < a.length; ++i) {
            total += a[i];
            cur = Math.max(0, cur + b[i] - a[i]);
            maxGain = Math.max(maxGain, cur);
        }
        return total + maxGain;
    }
}

